INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64514501', 64514501, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'PUSAT PELAPORAN DAN ANALISIS TRANSAKSI KEUANGAN', 'Pengadaan Pemeliharaan Chiller di Gedung PPATK TA 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 522200000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Pemeliharaan Chiller di Gedung PPATK TA 2026 Merk DAIKIN Model UAL230DM5M-FEMOA sebanyak 16 unit dan Merk DAIKIN Model UAL230D5-FABI sebanyak 6 unit', '1. Pemeliharaan Chiller meliputi: - Pemeriksaan jala-jala listrik - Pemeriksaan filter udara - Pembersihan body unit dan bagian-bagian mesin - Pengaturan kelembaban udara - Pembersihan diffuser - Pemberian minyak pelumas terhadap bagian-bagian mesin yang bergerak - Kebersihan lingkungan mesin dari kotoran - Pemeriksaan kebocoran refrigerant - Pembersihan sirip-sirip condenser dan coil AHU 2. Pemeliharaan Terjadwal: a) Sevice dilakukan 2 bulan sekali - Menganalisa operasional data unit yang sudah diambil - Membersihkan Coil dan fin condenser chiller dengan jet cleaner menggunakan air dan deterjen - Memeriksa kondisi olie compressor - Memeriksa Pressure drop oil filter - Memeriksa Heater oli - Memeriksa beban compressor (Operational load dan Unload) - Memeriksa Valve Expansi - Memeriksa pressure drop Air Chiller (Chilled water) - Memeriksa settingan dan pengoperasian compressor, temperature, tekanan, overloadtrip dan parameter lain - Setting dan kalibrasi controller - Memeriksa temperature discharge dan Suction - Memeriksa kontaktor dan komponen elektrikal - Membersihkan contact point contactor - Membersihkan body unit dan bagian-bagian mesin - Kebersihan lingkungan mesin dari kotoran - Pemeriksaan Kebocoran refrigerant - Memeriksa tegangan listrik - Memeriksa koneksi kabel - Mengisi log sheet setelah service - Mengevaluasi kondisi operasional unit chiller dan memberikan laporan - Berdiskusi dengan tim teknik PPATK dan memberikan rekomendasi jika ada yang harus dilakukan b). Service pemeliharaan Annual / tahunan - Memeriksa gulungan motor kompressor (mengger motor winding) - Setting dan kalibrasi main kontrol tahunan - Memeriksa terminal motor compressor 3. Menyampaikan laporan dilengkapi dengan dokumentasi pada setiap kali melaksanakan kunjungan pemeliharaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1594417);
